package com.bank.qa.data;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

// Simulates a shared backend; detects any key collision between workers.
class DataStore {
    private static final Logger log = Logger.getLogger(DataStore.class.getName());
    private final Map<String, Account> store = new ConcurrentHashMap<>();
    private volatile boolean collision = false;

    void create(Account a) {
        Account prev = store.putIfAbsent(a.id, a);
            if (prev != null) { collision = true;
            log.severe("COLLISION on id=" + a.id); }
    }
    int size() { return store.size(); }
    boolean hadCollision() { return collision; }
}
