package com.bank.qa.data;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class TestDataDemo {
    private static final Logger log = Logger.getLogger(TestDataDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DataLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        DataStore store = new DataStore();

        // Simulate 4 parallel WORKERS, each with its own factory (isolated data).
        int workers = 4, perWorker = 25;
        ExecutorService pool = Executors.newFixedThreadPool(workers);
        List<Future<?>> futures = new ArrayList<>();
        for (int w = 0; w < workers; w++) {
            final int workerIndex = w;
            futures.add(pool.submit(() -> {
                AccountFactory factory = new AccountFactory(workerIndex); // per-worker
                for (int i = 0; i < perWorker; i++) {
                    // independent setup: each "test" creates its OWN uniquely-keyed data
                    Account a = factory.newAccount("Cust-" + workerIndex + "-" + i,
                            new BigDecimal("50000"));
                    store.create(a);
                }
            }));
        }
        for (Future<?> f : futures) f.get();
        pool.shutdown();

        log.info("Created " + store.size() + " accounts across " + workers + " workers");
        log.info("Collisions: " + store.hadCollision()
            + (store.hadCollision() ? " (BAD)" : " (none — unique keys worked)"));
        log.info("Expected unique count = " + (workers * perWorker)
            + ", actual = " + store.size());

        // Static fixture note (read-only reference data, safe to share):
        log.info("Reference data loaded read-only from reference-accounts.json "
            + "(shared safely because nothing writes to it).");
    }
}

// ─── Would be in DataLogFormatter.java in a real project ───
class DataLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
